"use client";

import { useState } from "react";
import {
  type StutterState,
  stutterDevice,
} from "@/components/audio-ui/devices/stutter/device";
import { createStutterEngine } from "@/components/audio-ui/devices/stutter/engine";
import { StutterPanel } from "@/components/audio-ui/devices/stutter/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * A stutter you can plug in: its state, a panel that draws one interval and
 * an engine that plays it, each its own file and none knowing the others. Play
 * the loop and switch it on: it catches a slice and repeats it.
 */
export function BlockStutter() {
  const [state, setState] = useState<StutterState>(() =>
    stutterDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createStutterEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-none h-full w-full min-w-0">
      <StutterPanel onValueChange={setState} value={state} />
    </div>
  );
}
